changeSet.sql:
ALTER TABLE integration.myid_profile ADD COLUMN IF NOT EXISTS user_in TEXT;

UPDATE integration.myid_profile p
   SET user_in = (SELECT COALESCE(u.pinfl, u.tin) FROM "user"."user" u WHERE u.id = p.user_id)
 WHERE p.user_id IS NOT NULL;

UPDATE integration.myid_profile p
   SET user_in = p.pinfl
 WHERE p.user_in IS NULL AND p.pinfl IS NOT NULL;

ALTER TABLE integration.myid_profile DROP COLUMN IF EXISTS user_id;
